import {simulate,clock,status,delay,reason,END,placeName} from './sim.mjs';
import {initFloor,updateFloor} from './floor.mjs';
let t=0,conflict=30,playing=false,speed=1,selected='US',filter='all',last=performance.now();let s;
const $=id=>document.getElementById(id);
initFloor($('map'));
const shownDelay=c=>Math.floor(delay(c,t));
function caseForRoom(n){return s.cases.find(c=>c.room===n&&c.start!==null&&t<c.end)||s.cases.find(c=>c.room===n&&c.start===null&&t>=c.plan)}
function render(){s=simulate(conflict,t);$('clock').textContent=clock(t);$('scrub').value=t;$('runstate').textContent=playing?'Running':'Paused';$('play').textContent=playing?'Pause':'Play';$('duration').textContent=`${conflict} min`;$('conflict').value=conflict;$('asof').textContent=`As of ${clock(t)}`;
const late=s.cases.filter(c=>shownDelay(c)>0);$('late').textContent=late.length;$('minutes').innerHTML=late.reduce((a,c)=>a+shownDelay(c),0)+'<span> min</span>';
renderMotion();
$('schedule').innerHTML=`<div class="axis"><span></span><div class="ticks">${Array.from({length:8},(_,i)=>`<span>${clock(i*30)}</span>`).join('')}</div></div>`+s.cases.map(c=>{const d=shownDelay(c);return `<div class="timeline-row"><button class="case-label" data-entity="${c.id}">Case ${c.id}<small>OR ${c.room} ${d?`· +${d}m`:''}</small></button><div class="track"><span class="bar plan" style="left:${c.plan/END*100}%;width:${c.duration/END*100}%" title="Planned ${clock(c.plan)}–${clock(c.plan+c.duration)}"></span>${d?`<span class="bar delay" style="left:${c.plan/END*100}%;width:${d/END*100}%" title="Observed start delay ${d} minutes"></span>`:''}${c.start!==null&&t>c.start?`<span class="bar actual" style="left:${c.start/END*100}%;width:${(Math.min(t,c.end)-c.start)/END*100}%" title="Actual start ${clock(c.start)}; ${status(c,t)}"></span>`:''}<span class="now-line" style="left:${t/END*100}%"></span></div></div>`}).join('');
renderInspector();let events=s.events.filter(e=>filter==='delay'?e.kind==='delay':filter==='movement'?e.kind==='movement':filter==='selected'?matches(e.entity):true).slice().reverse();$('events').innerHTML=events.map(e=>`<div class="event ${e.kind==='delay'?'delayed':''}"><time>${clock(e.time)}</time><button data-entity="${e.entity}">${e.entity==='US'?'US-01':/^[SNA][123]$/.test(e.entity)?e.entity:`Case ${e.entity}`}</button><span>${e.text}</span></div>`).join('')||'<div class="empty">No matching events at this time.</div>';
}
function matches(id){if(selected===id)return true;if(selected.startsWith('OR')&&/^[SNA][123]$/.test(id))return id[1]===selected.slice(2);if(selected.startsWith('OR'))return s.cases.some(c=>c.id===id&&c.room===+selected.slice(2));if(/^[SNA][123]$/.test(selected))return s.cases.some(c=>c.id===id&&c.room===+selected.slice(1));return false}
function renderInspector(){let title,desc,facts=[],dep='';const c=s.cases.find(c=>c.id===selected);
if(c){title=`Patient P-${c.id} / Case ${c.id}`;desc=status(c,t);facts=[['Location',!c.arrived?'Outside suite':c.start===null?'Pre-op':t<c.end?`OR ${c.room}`:c.discharge===null?'Recovery':'Departed'],['Planned start',clock(c.plan)],['Actual start',c.start===null?'Not started':clock(c.start)],['Start delay',`${shownDelay(c)} min`],['Required',`OR ${c.room} · S${c.room}, N${c.room}, A${c.room}${c.us?' · US-01':''}`]];dep=c.start===null?reason(c,s):c.prior?`Case ${c.prior} → room turnover (15 min) → OR ${c.room} and team → case ${c.id}`:`US-01 → case ${c.id} → room turnover (15 min) → case ${{A:'D',B:'E',C:'F'}[c.id]}`}
else if(selected==='US'){title='US-01';desc='Shared ultrasound machine';facts=[['Location',placeName(s.machine.location)],['State',s.machine.status],['Assigned to',s.machine.owner?`Case ${s.machine.owner}`:'None'],['Extra hold',`${conflict} min · synthetic`],['Turnaround','3 min clean + 2 min travel'],...(s.machine.motion?[['Route',`${placeName(s.machine.motion.from)} → ${placeName(s.machine.motion.to)}`],['Arrival',clock(s.machine.motion.arrive)]]:[])];dep=`US-01 → case A → case B → case C. Each case requires exclusive use to start. ${['Cleaning','In transit'].includes(s.machine.status)?'Currently unavailable during turnaround.':''}`}
else if(/^[SNA][123]$/.test(selected)){const n=+selected.slice(1),roles={S:'Surgeon',N:'Nurse',A:'Anesthesia staff'};title=`${selected} · ${roles[selected[0]]}`;desc='Synthetic dedicated team member';const person=s.staff.find(p=>p.id===selected);const current=s.cases.find(c=>c.room===n&&c.start!==null&&t<c.end);facts=[['Location',placeName(person.location)],['State',person.motion?'Walking':current?'In case':person.location==='REC'?'Recovery handoff':person.location===`OR${n}`?'Room duties / waiting':'Between cases'],['Assigned cases',s.cases.filter(c=>c.room===n).map(c=>c.id).join(', ')],...(person.motion?[['Route',`${placeName(person.motion.from)} → ${placeName(person.motion.to)}`],['Arrival',clock(person.motion.arrive)]]:[])];dep='Synthetic routine: '+({S:'Visits the office after a case, then returns for the next start.',N:'Stays 10 minutes for room duties, visits the workroom, then returns.',A:'Walks to recovery for a 3-minute handoff, then to the lounge and back.'}[person.role])+' Walking takes 2 simulated minutes per trip.'}
else if(selected.startsWith('OR')){const n=+selected.slice(2),c=caseForRoom(n);title=`Operating room ${n}`;desc=c?`Case ${c.id} · ${status(c,t)}`:'No case running';facts=[['Team',`S${n} · N${n} · A${n}`],['Cases',s.cases.filter(c=>c.room===n).map(c=>c.id).join(' → ')],['Turnover','15 min after each case']];dep=c?reason(c,s):'The next case needs its patient, room, dedicated team and any required equipment.'}
else{title=placeName(selected);desc='Synthetic hospital floor zone';const purpose={PRE:'Patient preparation and waiting',REC:'30-minute recovery / staff handoff',HUB:'Shared equipment storage',WORK:'Nursing preparation and documentation',OFFICE:'Surgeon between-case work',LOUNGE:'Staff between-case time'};facts=[['Staff here',s.staff.filter(p=>p.location===selected).map(p=>p.id).join(', ')||'None'],['Purpose',purpose[selected]||'Connecting rooms']];dep='Room assignments and staff routines are illustrative. Patient capacity is unconstrained; this floor is not a validated hospital plan.'}
$('inspector').innerHTML=`<h2>${title}</h2><p>${desc}</p><dl class="facts">${facts.map(([k,v])=>`<dt>${k}</dt><dd>${v}</dd>`).join('')}</dl><div class="dependency">${dep}</div>`}
function pause(){playing=false;last=performance.now()}
document.addEventListener('click',e=>{const el=e.target.closest('[data-entity]');if(el){selected=el.dataset.entity;render()}});document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('[role=button]')){e.preventDefault();selected=e.target.dataset.entity;render()}});
$('play').onclick=()=>{if(t>=END)t=0;playing=!playing;last=performance.now();render()};$('reset').onclick=()=>{pause();t=0;conflict=30;selected='US';filter='all';$('filter').value=filter;speed=1;$('speed').value=1;render()};$('rewind').onclick=()=>{pause();t=Math.max(0,t-10);render()};$('next').onclick=()=>{pause();t=simulate(conflict,END).events.find(e=>e.time>t)?.time??END;render()};$('scrub').oninput=e=>{pause();t=+e.target.value;render()};$('speed').onchange=e=>speed=+e.target.value;$('conflict').oninput=e=>{pause();conflict=+e.target.value;render()};$('jump').onclick=()=>{pause();t=20;render()};$('filter').onchange=e=>{filter=e.target.value;render()};$('about').onclick=()=>$('aboutDialog').showModal();$('closeAbout').onclick=()=>$('aboutDialog').close();
function renderMotion(){const moving=updateFloor(s,t,selected);$('movement-status').textContent=moving.length?moving.join(' · '):'No one in transit · press Play or try a movement shortcut';$('movement-count').textContent=`${moving.length} moving`;}
function demo(at){pause();t=at;speed=1;$('speed').value='1';playing=true;last=performance.now();render();}
$('watch-staff').onclick=()=>demo(45+conflict-1);$('watch-equipment').onclick=()=>demo(15+conflict+2);
setInterval(()=>{const now=performance.now();const dt=(now-last)*speed/1000;last=now;if(playing){const before=Math.floor(t);t=Math.min(END,t+dt);if(t===END)playing=false;if(Math.floor(t)!==before||!playing)render();else renderMotion()}},40);render();
